effect.shader:
vec3 hash33(vec3 p) {
p = vec3(dot(p, vec3(127.1, 311.7, 74.7)),
dot(p, vec3(269.5, 183.3, 246.1)),
dot(p, vec3(113.5, 271.9, 124.6)));
return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
}
float perlinNoise3D(vec3 p) {
vec3 pi = floor(p);
vec3 pf = p - pi;
vec3 g000 = hash33(pi + vec3(0.0, 0.0, 0.0));
vec3 g100 = hash33(pi + vec3(1.0, 0.0, 0.0));
vec3 g010 = hash33(pi + vec3(0.0, 1.0, 0.0));
vec3 g110 = hash33(pi + vec3(1.0, 1.0, 0.0));
vec3 g001 = hash33(pi + vec3(0.0, 0.0, 1.0));
vec3 g101 = hash33(pi + vec3(1.0, 0.0, 1.0));
vec3 g011 = hash33(pi + vec3(0.0, 1.0, 1.0));
vec3 g111 = hash33(pi + vec3(1.0, 1.0, 1.0));
float n000 = dot(g000, pf);
float n100 = dot(g100, pf - vec3(1.0, 0.0, 0.0));
float n010 = dot(g010, pf - vec3(0.0, 1.0, 0.0));
float n110 = dot(g110, pf - vec3(1.0, 1.0, 0.0));
float n001 = dot(g001, pf - vec3(0.0, 0.0, 1.0));
float n101 = dot(g101, pf - vec3(1.0, 0.0, 1.0));
float n011 = dot(g011, pf - vec3(0.0, 1.0, 1.0));
float n111 = dot(g111, pf - vec3(1.0, 1.0, 1.0));
vec3 u = pf * pf * (3.0 - 2.0 * pf);
float nx00 = mix(n000, n100, u.x);
float nx10 = mix(n010, n110, u.x);
float nx01 = mix(n001, n101, u.x);
float nx11 = mix(n011, n111, u.x);
float nxy0 = mix(nx00, nx10, u.y);
float nxy1 = mix(nx01, nx11, u.y);
return mix(nxy0, nxy1, u.z);
}
float fbm3D(vec3 p, int octaves) {
float value = 0.0;
float amplitude = 0.8;
float frequency = 0.13;
for (int i = 0; i < 4; i++) {
if (i >= octaves) break;
value += amplitude * perlinNoise3D(p * frequency);
amplitude *= 0.5;
frequency *= 2.0;
}
return value;
}
void main() {
vec2 suv = acScreenNorm.xy;
vec2 uv = acLayerNorm.xy;
float aspect = acLayerSize.x / acLayerSize.y;
uv = (uv - 0.5) * 2.0;
uv.x *= aspect;
vec3 p = vec3(uv * 3.0, acTime * speed);
float noise = fbm3D(p, 4);
noise = (noise + 1.0) * 0.5;
float wave = noise * 6.28318 * globalFreq;
float rC = 0.5 + 0.5 * sin(wave * freqRed + phaseRed);
float gC = 0.5 + 0.5 * sin(wave * freqGreen + phaseGreen);
float bC = 0.5 + 0.5 * sin(wave * freqBlue + phaseBlue);
vec3 col = vec3(rC, gC, bC);
float gray = dot(col, vec3(0.299, 0.587, 0.114));
col = mix(vec3(gray), col, clamp(saturation, 0.0, 2.0));
col *= brightness;
vec4 base = texture2DCv(inputImg.texture, suv);
vec4 effectCol = vec4(col * base.a, base.a);
gl_FragColor = mix(base, effectCol, blend);
}
